customMethods.script:

userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)
attrInfo = dict(self.view.custom.dataSource.info)

if attrInfo['attributeDataSourceId'] is None:
	attributeDataSourceId, msg = system.kanoa.quality.config.addDataSource(attrInfo, userId)
	if msg is None: 
		self.view.custom.dataSource.info.attributeDataSourceId = attributeDataSourceId
		system.perspective.sendMessage('showSuccessfulToast', {'message': "Attribute datasource has been added"})		
	else: system.perspective.sendMessage('showFailerToast', {'message': msg})		
else:
	retVal, msg = system.kanoa.quality.config.updateDataSource(attrInfo, userId)
	if msg is None:	system.perspective.sendMessage('showSuccessfulToast', {'message': "Attribute datasource has been updated"})		
	else: system.perspective.sendMessage('showFailerToast', {'message': msg})				

self.view.refreshBinding("custom.dataSource.table.data")

return

userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)
for row in self.view.custom.dataSource.table.selection.data:
	retVal, msg = system.kanoa.quality.config.deleteDataSource(row['attributeDataSourceId'], userId)
	if retVal: system.perspective.sendMessage('showSuccessfulToast', {'message': "Data source has been deleted"})	
	else: system.perspective.openPopup('msg', 'kanoa/core/templates/displays/messagePopup', params = {'text':msg}, showCloseIcon=True, draggable=True, resizeable=True)

self.view.refreshBinding("custom.dataSource.table.data")	

return

userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)	
for row in self.view.custom.tolerances.table.selection.data:
	retVal, msg = system.kanoa.quality.config.deleteTolerance(row['attributeToleranceId'], userId)
	if retVal: system.perspective.sendMessage('showSuccessfulToast', {'message': "Data source has been deleted"})	
	else: system.perspective.openPopup('msg', 'kanoa/core/templates/displays/messagePopup', params = {'text':msg}, showCloseIcon=True, draggable=True, resizeable=True)

self.view.refreshBinding("custom.tolerances.table.data")	

return

